:root {
  --bg-board: #1a0a2e;
  --bg-entry: #2d1b4e;
  --bg-entry-hover: #3a2460;
  --border-board: #7b2fff;
  --border-entry: #4a2080;
  --color-gold: #ffd700;
  --color-silver: #c0c8d8;
  --color-bronze: #cd7f32;
  --color-default: #8888aa;
  --color-title: #ff00ff;
  --color-subtitle: #00ffcc;
  --color-score: #ffffff;
  --color-rank: #aaaacc;
  --color-footer: #6644aa;
  --bar-gold: #ffd700;
  --bar-silver: #c0c8d8;
  --bar-bronze: #cd7f32;
  --bar-default: #5544aa;
  --color-credits: #ff4488;
}

.arcade-board {
  background-color: var(--bg-board);
  border: 3px solid var(--border-board);
  border-radius: 12px;
  padding: 16px 20px;
  width: 480px;
  margin: 0 auto;
}

.board-header {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-bottom: 4px;
}

.header-icon {
  font-size: 20px;
}

.board-title {
  font-size: 26px;
  font-weight: 900;
  color: var(--color-title);
  letter-spacing: 6px;
  margin: 0;
}

.board-subtitle {
  text-align: center;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 3px;
  color: var(--color-subtitle);
  margin-bottom: 14px;
}

.leaderboard {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 14px;
}

.entry {
  display: flex;
  align-items: center;
  gap: 10px;
  background-color: var(--bg-entry);
  border: 1px solid var(--border-entry);
  border-radius: 6px;
  padding: 8px 12px;
}

.rank {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--color-rank);
  width: 28px;
  flex-shrink: 0;
}

.initials {
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 2px;
  width: 36px;
  flex-shrink: 0;
}

.entry--gold .initials { color: var(--color-gold); }
.entry--silver .initials { color: var(--color-silver); }
.entry--bronze .initials { color: var(--color-bronze); }
.entry .initials { color: var(--color-default); }

.score-bar {
  flex: 1;
  height: 6px;
  border-radius: 3px;
}

.score-bar--gold { background-color: var(--bar-gold); width: 95%; }
.score-bar--silver { background-color: var(--bar-silver); width: 82%; }
.score-bar--bronze { background-color: var(--bar-bronze); width: 70%; }
.score-bar--default { background-color: var(--bar-default); }

.score {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--color-score);
  width: 72px;
  text-align: right;
  flex-shrink: 0;
}

.board-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid var(--border-entry);
  padding-top: 10px;
}

.footer-text {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 1px;
  color: var(--color-footer);
}

.credits {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 2px;
  color: var(--color-credits);
}
